(159L,'c5b8') AS i(code,value)),
parts AS (
 SELECT t.*,e.entity,e.value,
 CASE WHEN token RLIKE r'^&#[xX]' THEN try_cast(conv(regexp_extract(token,r'^&#[xX]([0-9a-fA-F]+)',1),16,10) AS BIGINT)
 WHEN token RLIKE r'^&#[0-9]' THEN try_cast(regexp_extract(token,r'^&#([0-9]+)',1) AS BIGINT) END code,
 row_number() OVER(PARTITION BY pos ORDER BY length(e.entity) DESC NULLS LAST) rank
 FROM tokens t LEFT JOIN entities e ON substring(t.token,1,1)='&' AND startswith(substring(t.token,2),e.entity)
), decoded AS (
 SELECT pos,CASE
 WHEN p.code IS NOT NULL THEN CASE
  WHEN i.code IS NOT NULL THEN i.value
  WHEN p.code>1114111 OR p.code BETWEEN 55296 AND 57343 THEN decode(unhex('efbfbd'),'UTF-8')
  WHEN p.code BETWEEN 1 AND 8 OR p.code=11 OR p.code BETWEEN 14 AND 31 OR p.code BETWEEN 127 AND 159
    OR p.code BETWEEN 64976 AND 65007 OR pmod(p.code,65536) IN (65534,65535) THEN ''
  ELSE from_json(concat('{"v":"',CASE WHEN p.code<=65535 THEN concat('\\u',lpad(hex(p.code),4,'0'))
   ELSE concat('\\u',lpad(hex(55296+((p.code-65536) DIV 1024)),4,'0'),'\\u',lpad(hex(56320+pmod(p.code-65536,1024)),4,'0')) END,'"}'),'v STRING').v END
 WHEN p.entity IS NOT NULL THEN concat(p.value,substring(p.token,length(p.entity)+2))
 ELSE p.token END text
 FROM parts p LEFT JOIN invalid i ON i.code=p.code WHERE rank=1
)
SELECT CASE WHEN s IS NULL THEN NULL ELSE concat_ws('',transform(array_sort(collect_list(named_struct('pos',pos,'text',text))),x->x.text)) END FROM decoded;
